function fillRandom(buffer) {
  let from = 0
  while (from < buffer.length) {
    let to = Math.min(from + GET_RANDOM_LIMIT, buffer.length)
    crypto.getRandomValues(buffer.subarray(from, to))
    from = to
  }
}

test(`recovers from crypto errors`, () => {
  nanoid(1)
  let original = crypto.getRandomValues
  crypto.getRandomValues = () => {
    throw new Error('Entropy failure')
  }
  try {
    throws(() => {
      nanoid(65536)
    }, /Entropy failure/)
    throws(() => {
      random(131072)
    }, /Entropy failure/)
  } finally {
    crypto.getRandomValues = original
  }
  equal(nanoid().length, 21)
  equal(random(10).length, 10)
})
